"""Actual room rendering, ordinary movement, persistence, touch and transition regression checks."""
import json,pathlib
from playwright.sync_api import sync_playwright
OUT=pathlib.Path(__file__).resolve().parents[2]/'docs/adventures-v9';(OUT/'screenshots').mkdir(parents=True,exist_ok=True)
result={'environment':'Managed Chromium SwiftShader; phone/tablet touch emulation and injected standard Gamepad API snapshots, NOT physical iPhone/Lenovo/Safari/Xbox tests. RAF paused for deterministic ordinary update steps.','checks':[],'routes':[]}
def check(name,ok,detail=None):
 result['checks'].append({'name':name,'passed':bool(ok),'detail':detail});(OUT/'interiors.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS'if ok else'FAIL',name,detail or '',flush=True);assert ok,name

def render(g,name):
 g.evaluate('''()=>{const g=adventure.game;g.debugCamera=false;g.cameraPosition.set(0,0,0);g.cameraUpdate(1/60);g.updateContext();g.renderScene();document.getElementById('toast').hidden=true;}''');g.screenshot(path=str(OUT/'screenshots'/f'{name}.png'))

def walk(g,x,z,name):
 row=g.evaluate('''({x,z})=>{const g=adventure.game,start={...g.player},samples=[];g.cameraYaw=0;let reached=false,maxRise=0,old=g.player.y;for(let i=0;i<2400;i++){const dx=x-g.player.x,dz=z-g.player.z,len=Math.hypot(dx,dz);if(len<.08){reached=true;break;}g.update(1/120,{x:dx/len*.65,z:dz/len*.65,run:false});maxRise=Math.max(maxRise,Math.abs(g.player.y-old));old=g.player.y;if(i%24===0)samples.push({x:g.player.x,y:g.player.y,z:g.player.z});}g.velocity.set(0,0);g.controls.clear();return{start,end:{...g.player},reached,maxRise,samples}}''',{'x':x,'z':z});result['routes'].append({'name':name,**row});check(name,row['reached'] and row['maxRise']<.18,{'end':row['end'],'maxRise':row['maxRise']});return row
with sync_playwright()as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 for device,size in [('tablet',{'width':1024,'height':768}),('phone',{'width':390,'height':844})]:
  c=b.new_context(viewport=size,has_touch=True,is_mobile=True,device_scale_factor=1);g=c.new_page();g.set_default_timeout(120000);errors=[];g.on('pageerror',lambda e:errors.append(str(e)));g.goto('http://127.0.0.1:5175/adventures.html?test=1');g.wait_for_function('window.adventure?.ready');g.locator('#enter').click();g.evaluate('window.requestAnimationFrame=()=>0');g.wait_for_timeout(120)
  setup=g.evaluate('''async()=>{const g=adventure.game;window.originalId=g.session.current.id;window.entries=g.landscape.entrances.filter(e=>e.kind==='townhouse');window.firstEntry=entries[0];Object.assign(g.player,{x:firstEntry.x,z:firstEntry.z,y:0});g.cameraYaw=firstEntry.yaw;g.cameraPitch=.47;g.updateContext();g.cameraPosition.set(0,0,0);g.cameraUpdate(1/60);g.renderScene();return {prompt:document.getElementById('interact').textContent,id:g.entryNear?.id,entry:firstEntry,stats:g.stats(),entrances:g.landscape.entrances.length}}''');check(device+' exterior entrance has compact Enter prompt',setup['id']==setup['entry']['id'] and 'Enter' in setup['prompt'],setup);render(g,device+'-exterior-entrance')
  g.locator('#interact').tap();g.evaluate('()=>{adventure.game.discover();adventure.game.discover()}');g.wait_for_function('!adventure.game.transitioning&&!!adventure.game.interior')
  entered=g.evaluate('''async()=>{const g=adventure.game,old=await g.session.store.load(originalId);return {originalId,current:g.session.current.id,version:g.data.version,inside:g.data.inside.id,count:(await g.session.store.list()).length,oldVersion:old.snapshot.world.adventure.version,oldObjects:old.snapshot.world.adventure.objects,worldVisible:g.landscape.group.visible,objects:g.data.objects,stats:g.stats(),pose:g.worldMap.pose,returnPose:g.data.inside.outside,joystick:g.controls.stick}}''');check(device+' rapid entry creates exactly one interior copy and retains original',entered['count']==2 and entered['originalId']!=entered['current'] and entered['oldVersion']==1 and entered['version']==2 and entered['inside']==setup['entry']['id'],entered);check(device+' outdoor geometry suspended and original constructions untouched',not entered['worldVisible'] and entered['oldObjects']==entered['objects']);check(device+' minimap stays at actual exterior entrance indoors',entered['pose']['x']==entered['returnPose']['x'] and entered['pose']['z']==entered['returnPose']['z']);render(g,device+'-room-ground')
  # Move an existing furnishing through the same confirmed edit path and preserve it in this room only.
  edit=g.evaluate('''()=>{const g=adventure.game,p=g.objects.find(p=>p.id==='rug');g.beginPlacement(p.asset,p);g.placementAnchor={x:p.x+.25,z:p.z};g.updateGhost();const problem=g.placementProblem(g.pending,g.ghost);if(!problem)g.confirmEdit();return{problem,objects:g.objects.map(p=>({...p})),outside:g.data.objects}}''');check(device+' confirmed room furnishing edit works',not edit['problem'],edit['problem'])
  e=setup['entry'];sx=e['width']/2-1;top=-e['depth']/2+1.35;bottom=e['depth']/2-1.3
  walk(g,0,bottom+.5,device+' walks to stair approach');walk(g,sx,bottom+.5,device+' walks across ground-floor approach');walk(g,sx,(top+bottom)/2,device+' walks halfway upstairs');render(g,device+'-stair-midpoint');walk(g,sx,top-.6,device+' walks onto upper landing');check(device+' reaches actual upper floor',g.evaluate('adventure.game.player.y>2.99'))
  walk(g,0,top-.6,device+' walks from landing into upper room');render(g,device+'-upper-room')
  # Real store reload at upper floor. Local coordinates, elevation, room and edits must survive.
  reloaded=g.evaluate('''async()=>{const g=adventure.game;await g.session.save();const id=g.session.current.id,before=JSON.stringify(g.objects),y=g.player.y;await g.session.open(id);return {inside:g.data.inside.id,y:g.player.y,before,after:JSON.stringify(g.objects),map:!!g.worldMap.data,visible:g.landscape.group.visible}}''');check(device+' upper-floor reload retains correct room, floor, edits and map',reloaded['inside']==setup['entry']['id'] and abs(reloaded['y']-3)<.01 and reloaded['before']==reloaded['after'] and reloaded['map'] and not reloaded['visible'],reloaded)
  walk(g,sx,top-.6,device+' returns to upper landing');walk(g,sx,bottom+.5,device+' walks downstairs');check(device+' returns to ground floor using movement',g.evaluate('adventure.game.player.y<.01'));walk(g,0,bottom+.5,device+' returns to exit')
  # Unmodified keyboard and injected pad movement feed the same actual room physics.
  g.keyboard.down('w');keyboard=g.evaluate('''()=>{const g=adventure.game,z=g.player.z;for(let i=0;i<30;i++)g.update(1/120);return g.player.z<z-.3}''');g.keyboard.up('w');check(device+' keyboard room movement uses ordinary controls',keyboard)
  walk(g,0,bottom+.5,device+' returns after keyboard check')
  # CDP touch joystick in the real browser; release must clear input.
  session=c.new_cdp_session(g);r=g.locator('#joystick').bounding_box();cx=r['x']+r['width']/2;cy=r['y']+r['height']/2
  session.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':cx,'y':cy,'id':1}]});session.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':cx,'y':cy-34,'id':1}]})
  touch=g.evaluate('''()=>{const g=adventure.game,z=g.player.z,s={...g.controls.stick};for(let i=0;i<30;i++)g.update(1/120);return {moved:g.player.z<z-.2,stick:s}}''');session.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});check(device+' real touch joystick moves and releases inside',touch['moved'] and g.evaluate('adventure.game.controls.stick.y===0'),touch)
  walk(g,0,bottom+.5,device+' returns after touch check')
  pad=g.evaluate('''()=>{const g=adventure.game,pad={index:0,connected:true,mapping:'standard',axes:[0,0,0,0],buttons:Array.from({length:16},()=>({pressed:false,value:0}))};g.controls.gamepad.sample([pad]);pad.axes[1]=-.8;g.controls.gamepad.sample([pad]);const z=g.player.z;for(let i=0;i<30;i++)g.update(1/120);const moved=g.player.z<z-.2;g.controls.gamepad.sample([]);return{moved,released:g.controls.gamepad.state.z===0}}''');check(device+' injected standard gamepad room movement and disconnect fallback',pad['moved'] and pad['released'],pad)
  walk(g,0,bottom+.5,device+' returns after pad check');g.evaluate('adventure.game.updateContext()');g.locator('#interact').tap();g.wait_for_function('!adventure.game.transitioning&&!adventure.game.interior');exited=g.evaluate('''()=>{const g=adventure.game;return {x:g.player.x,z:g.player.z,inside:g.data.inside??null,worldVisible:g.landscape.group.visible,roomCount:Object.keys(g.data.rooms).length}}''');check(device+' exit returns safely to the exact same exterior entrance',abs(exited['x']-setup['entry']['x'])<.01 and abs(exited['z']-setup['entry']['z'])<.01 and exited['inside'] is None and exited['worldVisible'],exited);render(g,device+'-exit')
  # Same template, different stable building ID: default furnishings, independent edits.
  second=g.evaluate('''async()=>{const g=adventure.game,e=entries[1];Object.assign(g.player,{x:e.x,z:e.z});await g.enterRoom(e);return{inside:g.data.inside.id,copyCount: (await g.session.store.list()).length,rug:g.objects.find(p=>p.id==='rug').x,firstRug:g.data.rooms[firstEntry.id].objects.find(p=>p.id==='rug').x}}''');check(device+' matching buildings keep independent contents without another world copy',second['inside']!=setup['entry']['id'] and second['rug']!=second['firstRug'] and second['copyCount']==2,second)
  # Native checksummed export/import makes a new world and retains the active upper/lower room scope.
  backup=g.evaluate('''async()=>{const g=adventure.game,text=g.session.export(),old=g.session.current.id;await g.session.import(text);return {different:g.session.current.id!==old,inside:g.data.inside.id,rooms:Object.keys(g.data.rooms).length,oldStillExists:!!(await g.session.store.load(old))}}''');check(device+' native backup import retains rooms and preserves source record',backup['different'] and backup['rooms']==2 and backup['oldStillExists'],backup)
  # Full actual-world map while indoors keeps the exterior marker; explicit travel safely exits.
  g.locator('#minimap').tap();g.select_option('#mapDestination','alderwick');g.wait_for_function('!adventure.game.transitioning&&!adventure.game.interior');check(device+' actual-world map travel exits room and arrives safely',g.evaluate('Math.hypot(adventure.game.player.x+131,adventure.game.player.z+55)<.01&&!adventure.game.modalOpen'))
  check(device+' overlays fit viewport with touch-sized exit and controls',g.evaluate('document.documentElement.scrollWidth<=innerWidth&&document.querySelector("#joystick").getBoundingClientRect().width>=90&&document.querySelector("#interact").getBoundingClientRect().height>=40'))
  check(device+' no runtime exceptions',not errors,errors);c.close()
 b.close()
